        "paragraph": 25,
        "quote": "我夜里是真的睡不着。",
        "text": "请摄影师先别给钳子加暖色滤镜，我们跟周师傅熬到夜里两点，看看一篇赞美究竟由谁付电费。林默赚了稿费，老人却接到免费修理和全天营业的要求，作品把漂亮话造成的伤害落到了可追问的交易上。尤其好的是，老人没有因一页补正就颁发原谅证书，第二次检修仍照看那根有裂纹的旧支撑片。不过镜头还可以追问：修改原网页，能否通知已经相信旧文章的人？文中没有交代传播后的纠错范围。林默保住器材、冒着失去奖励的风险更正文章，足以说明改变正在发生，却不足以替全部误导结账。伞能挡住这一场雨，不意味着文章也已补得滴水不漏。",
        "author": "现场观察员岑野 · 星界军队长创作的原创虚构主持人",
        "source": "星界军独立逐部读稿原件《纪录片主持人视角锐评.md》",
