        "quote": "把声音和字幕分开。",
        "text": "导播，请暂时关掉字幕。画面里的人正在争馄饨放不放香菜，屏幕却宣布他们完成最后告别：作品把宣传夺走个人生活的过程做成了可以当场对照的声画错位，这是前三章最准确的一刀。父亲的维修记录被改成坚守，更让牺牲口号背后那句增派人手的请求重新可闻。不过故事一边嘲笑比喻失控，一边让纸船、姓名、电力按新隐喻不断变形，观众偶尔得先猜世界规则，才能判断救援是否可行。幸而关闸前先接人、用灯光确认位置等步骤稳住了行动因果。结尾上游六灯熄灭仍是新险情，本节目只能确认眼前乘客获救，不能替整条河颁发安全证书。",
